import java.util.function.*;

public class Main {
    // Exactly one abstract method: a functional interface (default methods don't count)
    @FunctionalInterface
    interface Greeter {
        String greet(String name);
        default Greeter twice() { return n -> greet(greet(n)); }
    }

    public static void main(String[] args) {
        Function<String, Integer> len = String::length;          // apply
        Predicate<String> isEmpty = String::isEmpty;             // test
        Consumer<String> printer = s -> System.out.println("consumed: " + s); // accept
        Supplier<String> sup = () -> "supplied";                 // get
        UnaryOperator<String> up = String::toUpperCase;
        BinaryOperator<Integer> add = Integer::sum;
        IntPredicate even = n -> n % 2 == 0;                     // primitive: no boxing
        Greeter g = n -> "Hi " + n;

        System.out.println("Function: " + len.apply("hello"));
        System.out.println("Predicate: " + isEmpty.test(""));
        printer.accept("x");
        System.out.println("Supplier: " + sup.get());
        System.out.println("UnaryOperator: " + up.apply("abc"));
        System.out.println("BinaryOperator: " + add.apply(2, 3));
        System.out.println("IntPredicate(4): " + even.test(4));
        System.out.println("Greeter twice: " + g.twice().greet("Bob"));
    }
}

import java.util.function.*;

public class Main {
    private final String name = "Outer";

    void demo() {
        Supplier<String> lambda = () -> this.name;               // this = enclosing Main
        Supplier<String> anon = new Supplier<String>() {
            private int calls = 0;                               // anonymous classes can hold state
            @Override public String get() {
                calls++;
                return this.getClass().getSimpleName().isEmpty()
                        ? "anon#" + calls : "named";             // this = the anonymous object
            }
        };
        System.out.println("lambda this.name: " + lambda.get());
        System.out.println("anon call 1: " + anon.get());
        System.out.println("anon call 2: " + anon.get());
    }

    public static void main(String[] args) {
        new Main().demo();
        // A non-capturing lambda is usually one cached instance; anonymous classes always allocate
        Runnable a = () -> {};
        Runnable b = () -> {};
        System.out.println("lambda class is synthetic: " + a.getClass().isSynthetic());
        System.out.println("two lambdas, different classes: " + (a.getClass() != b.getClass()));
        Runnable r1 = new Runnable() { public void run() {} };
        Runnable r2 = new Runnable() { public void run() {} };
        System.out.println("anon instances distinct: " + (r1 != r2));
        System.out.println("anon class name: " + r1.getClass().getName());
    }
}

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.*;

public class Main {
    static int field = 0;   // fields are read live through "this"/the class, so mutation is allowed

    public static void main(String[] args) {
        int base = 10;                         // effectively final: never reassigned
        Supplier<Integer> s = () -> base + 1;  // value 10 is copied into the lambda
        // base = 20;  // would break "effectively final" and fail to compile
        System.out.println("captured copy: " + s.get());

        Runnable inc = () -> field++;          // mutating a field is fine (but not thread-safe)
        inc.run(); inc.run();
        System.out.println("field after 2 runs: " + field);

        // Workaround 1: a one-element array box (final reference, mutable content)
        int[] box = {0};
        List.of(1, 2, 3).forEach(x -> box[0] += x);
        System.out.println("array box sum: " + box[0]);

        // Workaround 2: AtomicInteger, safe even across threads
        AtomicInteger atomic = new AtomicInteger();
        List.of(1, 2, 3).forEach(atomic::addAndGet);
        System.out.println("atomic sum: " + atomic.get());

        // Best: a reduction, no mutation at all
        int sum = List.of(1, 2, 3).stream().mapToInt(Integer::intValue).sum();
        System.out.println("reduction sum: " + sum);
    }
}

import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        // 1. Static method reference
        Function<String, Integer> parse = Integer::parseInt;
        System.out.println("static: " + parse.apply("42"));

        // 2. Bound instance: receiver (System.out) is fixed when the reference is created
        Consumer<String> out = System.out::println;
        out.accept("bound: hello");

        // 3. Unbound instance: first parameter becomes the receiver
        Function<String, String> upper = String::toUpperCase;
        System.out.println("unbound: " + upper.apply("abc"));
        Comparator<String> cmp = String::compareTo;       // (a, b) -> a.compareTo(b)
        System.out.println("compareTo: " + cmp.compare("a", "b"));

        // 4. Constructor references
        Supplier<List<String>> mk = ArrayList::new;
        List<String> list = mk.get();
        list.add("x");
        System.out.println("constructor: " + list);
        IntFunction<String[]> arr = String[]::new;
        System.out.println("array ctor length: " + arr.apply(3).length);

        String[] words = Stream.of("b", "a", "c").sorted().toArray(String[]::new);
        System.out.println(Arrays.toString(words));

        String s = null;
        try { Supplier<Integer> bad = s::length; }          // receiver evaluated now
        catch (NullPointerException e) { System.out.println("bound null receiver: NPE immediately"); }
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        // Intermediate ops only describe the work: nothing prints here
        Stream<Integer> pipeline = Stream.of(1, 2, 3, 4)
                .filter(x -> { System.out.println("filter " + x); return x % 2 == 0; })
                .map(x -> { System.out.println("map    " + x); return x * 10; });
        System.out.println("pipeline built, nothing ran yet");

        // The terminal op triggers execution; each element goes through all stages in turn
        List<Integer> result = pipeline.collect(Collectors.toList());
        System.out.println("result: " + result);

        // Short-circuiting with an infinite source: only needed elements are pulled
        List<Integer> firstThree = Stream.iterate(1, x -> x + 1)
                .filter(x -> x % 3 == 0)
                .limit(3)
                .toList();
        System.out.println("first 3 multiples of 3: " + firstThree);

        // peek is skipped when count() can compute the size without traversing (Java 9+)
        long n = Stream.of(1, 2, 3).peek(x -> System.out.println("peek " + x)).count();
        System.out.println("count = " + n + " (peek printed nothing)");
        long n2 = Stream.of(1, 2, 3).filter(x -> true).peek(x -> System.out.println("peek " + x)).count();
        System.out.println("count = " + n2 + " (filter forces traversal)");
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("--- without sorted ---");
        Optional<Integer> r = Stream.of(1, 2, 3, 4)
                .filter(x -> { System.out.println("filter " + x); return x % 2 == 0; })
                .map(x -> { System.out.println("map " + x); return x * 10; })
                .findFirst();                    // short-circuits after the first hit
        System.out.println("result: " + r.get());

        System.out.println("--- with sorted() barrier ---");
        Optional<Integer> r2 = Stream.of(1, 2, 3, 4)
                .filter(x -> { System.out.println("filter " + x); return x % 2 == 0; })
                .map(x -> { System.out.println("map " + x); return x * 10; })
                .sorted()                        // buffers all upstream elements first
                .findFirst();
        System.out.println("result: " + r2.get());
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    record Order(String id, List<String> items) {}

    static Optional<String> find(String key) {
        return key.equals("a") ? Optional.of("Alice") : Optional.empty();
    }

    public static void main(String[] args) {
        List<Order> orders = List.of(
                new Order("o1", List.of("pen", "ink")),
                new Order("o2", List.of()),                 // empty inner list contributes nothing
                new Order("o3", List.of("book")));

        // map: 1 -> 1, gives a stream of lists
        System.out.println("map: " + orders.stream().map(Order::items).toList());
        // flatMap: 1 -> 0..n, flattened
        System.out.println("flatMap: " + orders.stream().flatMap(o -> o.items().stream()).toList());

        // split lines into words
        System.out.println("words: " + Stream.of("a b", "c d e").flatMap(l -> Stream.of(l.split(" "))).toList());

        // Optional: map vs flatMap
        Optional<Optional<String>> nested = Optional.of("a").map(Main::find);
        Optional<String> flat = Optional.of("a").flatMap(Main::find);
        System.out.println("map gives nested: " + nested);
        System.out.println("flatMap gives flat: " + flat);

        // drop empties with flatMap(Optional::stream)
        System.out.println("present only: " + Stream.of("a", "z", "a").map(Main::find)
                .flatMap(Optional::stream).toList());

        // mapMulti avoids creating a mini-stream per element
        List<Integer> mm = Stream.of(1, 2, 3).<Integer>mapMulti((x, sink) -> { sink.accept(x); sink.accept(x * 10); }).toList();
        System.out.println("mapMulti: " + mm);
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    record Emp(String name, String dept, int salary) {}

    public static void main(String[] args) {
        List<Emp> emps = List.of(new Emp("Ann", "Eng", 120), new Emp("Bob", "Eng", 100),
                new Emp("Cid", "Ops", 80), new Emp("Dee", "HR", 70), new Emp("Eve", "Ops", 90));

        System.out.println("default lists: " + new TreeMap<>(emps.stream()
                .collect(Collectors.groupingBy(Emp::dept, Collectors.mapping(Emp::name, Collectors.toList())))));

        System.out.println("count:   " + emps.stream().collect(
                Collectors.groupingBy(Emp::dept, TreeMap::new, Collectors.counting())));
        System.out.println("sum:     " + emps.stream().collect(
                Collectors.groupingBy(Emp::dept, TreeMap::new, Collectors.summingInt(Emp::salary))));

        // maxBy gives Optional values; collectingAndThen unwraps them
        Map<String, Emp> top = emps.stream().collect(Collectors.groupingBy(Emp::dept, TreeMap::new,
                Collectors.collectingAndThen(Collectors.maxBy(Comparator.comparingInt(Emp::salary)), Optional::get)));
        top.forEach((d, e) -> System.out.println("top " + d + ": " + e.name()));

        // multi-level grouping
        System.out.println("two-level: " + emps.stream().collect(Collectors.groupingBy(Emp::dept, TreeMap::new,
                Collectors.groupingBy(e -> e.salary() >= 100 ? "high" : "low", TreeMap::new, Collectors.counting()))));

        // partitioningBy always has both keys
        System.out.println("partition: " + emps.stream().collect(
                Collectors.partitioningBy(e -> e.salary() > 200, Collectors.counting())));
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> nums = List.of(1, 2, 3, 4, 5);
        System.out.println("input: " + nums);

        // reduce: immutable reduction, identity + associative accumulator
        int sum = nums.stream().reduce(0, Integer::sum);
        System.out.println("reduce sum: " + sum);

        // 3-arg reduce when result type differs from element type
        int totalLen = Stream.of("aa", "b", "cccc").reduce(0, (acc, s) -> acc + s.length(), Integer::sum);
        System.out.println("total length: " + totalLen);

        // collect: mutable reduction into a container (supplier, accumulator, combiner)
        ArrayList<Integer> evens = nums.stream().filter(n -> n % 2 == 0)
                .collect(ArrayList::new, ArrayList::add, ArrayList::addAll);
        System.out.println("collect list: " + evens);

        // A custom collector with Collector.of: joins numbers with '+'
        Collector<Integer, StringJoiner, String> plus = Collector.of(
                () -> new StringJoiner("+"), (j, n) -> j.add(String.valueOf(n)),
                StringJoiner::merge, StringJoiner::toString);
        System.out.println("custom collector: " + nums.stream().collect(plus));

        // reduce with a wrong identity gives wrong results in parallel
        int bad = nums.parallelStream().reduce(100, Integer::sum);   // 100 added once per chunk
        System.out.println("identity 100 sequential would be " + (100 + sum) + ", parallel gave a multiple-of-chunks result: " + (bad >= 115));
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        // Pitfall: shared mutable state. ArrayList is not thread-safe.
        List<Integer> unsafe = new ArrayList<>();
        try {
            IntStream.range(0, 100_000).parallel().forEach(unsafe::add);
        } catch (RuntimeException e) {
            System.out.println("unsafe forEach threw " + e.getClass().getSimpleName());
        }
        System.out.println("unsafe run finished; its size is unreliable");

        // Correct: let collect() manage per-thread containers and merge them
        List<Integer> safe = IntStream.range(0, 100_000).parallel().boxed().collect(Collectors.toList());
        System.out.println("collect size: " + safe.size());

        // Pure, associative reduction parallelises correctly
        long sum = LongStream.rangeClosed(1, 1_000_000).parallel().sum();
        System.out.println("parallel sum: " + sum);

        // forEach order is nondeterministic; forEachOrdered keeps encounter order
        StringBuilder sb = new StringBuilder();
        IntStream.range(0, 10).parallel().forEachOrdered(i -> sb.append(i));
        System.out.println("forEachOrdered: " + sb);

        // Custom pool: submit the whole pipeline into your own ForkJoinPool
        try {
            var pool = new java.util.concurrent.ForkJoinPool(2);
            long r = pool.submit(() -> LongStream.rangeClosed(1, 1000).parallel().sum()).get();
            pool.shutdown();
            System.out.println("custom pool sum: " + r);
        } catch (Exception e) { System.out.println(e); }
    }
}

import java.util.*;

public class Main {
    static int calls = 0;

    static String expensiveDefault() {
        calls++;
        System.out.println("  (computing default...)");
        return "default";
    }

    public static void main(String[] args) {
        Optional<String> present = Optional.of("value");
        Optional<String> empty = Optional.empty();

        System.out.println("orElse on present:");
        System.out.println("  " + present.orElse(expensiveDefault()));      // computed anyway
        System.out.println("orElseGet on present:");
        System.out.println("  " + present.orElseGet(Main::expensiveDefault)); // supplier skipped
        System.out.println("calls so far: " + calls);

        System.out.println("orElseGet on empty:");
        System.out.println("  " + empty.orElseGet(Main::expensiveDefault));

        // orElseThrow: absence is an error
        try {
            empty.orElseThrow(() -> new NoSuchElementException("user 7 not found"));
        } catch (NoSuchElementException e) {
            System.out.println("orElseThrow: " + e.getMessage());
        }

        // or() (Java 9) returns another Optional instead of a bare value
        System.out.println("or(): " + empty.or(() -> Optional.of("fallback")));
        // orElse(null) leaves the Optional world for legacy APIs
        System.out.println("orElse(null): " + empty.orElse(null));
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    record User(String name, String email) {
        // Good: Optional as a return type for "may not exist"
        Optional<String> emailOpt() { return Optional.ofNullable(email); }
    }

    static Optional<User> findUser(String name) {
        return name.equals("ann") ? Optional.of(new User("ann", "ann@example.test")) : Optional.empty();
    }

    public static void main(String[] args) {
        // Chain instead of isPresent()/get() ladders
        String domain = findUser("ann")
                .flatMap(User::emailOpt)
                .filter(e -> e.contains("@"))
                .map(e -> e.substring(e.indexOf('@') + 1))
                .orElse("unknown");
        System.out.println("domain: " + domain);
        System.out.println("missing user: " + findUser("zed").map(User::name).orElse("none"));

        findUser("zed").ifPresentOrElse(u -> System.out.println("found " + u),
                () -> System.out.println("no such user"));

        // Collections: return empty list, never Optional<List>
        List<String> tags = List.of();
        System.out.println("empty list is fine: " + tags.isEmpty());

        // Primitive specialisations avoid boxing
        OptionalInt max = IntStream.of(3, 9, 4).max();
        System.out.println("OptionalInt: " + max.getAsInt());

        // Optional.of(null) throws; use ofNullable for maybe-null values
        try { Optional.of(null); } catch (NullPointerException e) { System.out.println("Optional.of(null) -> NPE"); }
        System.out.println("ofNullable(null): " + Optional.ofNullable(null));
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        // Stateless ops: filter/map decide per element. sorted buffers everything first.
        System.out.println("--- limit alone: stops early ---");
        Stream.of(5, 3, 8, 1)
                .peek(x -> System.out.println("saw " + x))
                .limit(2)
                .forEach(x -> {});

        System.out.println("--- sorted before limit: sees all ---");
        List<Integer> top2 = Stream.of(5, 3, 8, 1)
                .peek(x -> System.out.println("saw " + x))
                .sorted()
                .limit(2)
                .toList();
        System.out.println("smallest two: " + top2);

        // distinct keeps a set of seen elements
        System.out.println("distinct: " + Stream.of(1, 2, 1, 3, 2).distinct().toList());

        // A stateful lambda is a bug: result depends on evaluation order
        Set<Integer> seen = new HashSet<>();
        List<Integer> dups = IntStream.range(0, 8).map(i -> i % 4).boxed()
                .filter(x -> !seen.add(x))     // works sequentially, breaks in parallel
                .toList();
        System.out.println("duplicates (sequential only): " + dups);

        // Already sorted source: sorted() is skipped
        System.out.println("TreeSet sorted: " + new TreeSet<>(List.of(3, 1, 2)).stream().sorted().toList());
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    @FunctionalInterface
    interface ThrowingFunction<T, R> { R apply(T t) throws Exception; }

    // Adapter: wraps a checked-exception lambda into a normal Function
    static <T, R> java.util.function.Function<T, R> wrap(ThrowingFunction<T, R> f) {
        return t -> {
            try { return f.apply(t); }
            catch (IOException e) { throw new UncheckedIOException(e); }
            catch (Exception e) { throw new RuntimeException(e); }
        };
    }

    static int parse(String s) throws IOException {
        if (s.equals("bad")) throw new IOException("cannot parse " + s);
        return Integer.parseInt(s);
    }

    record Result(String input, Integer value, String error) {}

    public static void main(String[] args) {
        List<String> inputs = List.of("1", "bad", "3");
        System.out.println("inputs: " + inputs);

        try {
            inputs.stream().map(wrap(Main::parse)).toList();
        } catch (UncheckedIOException e) {
            System.out.println("wrapped: " + e.getCause().getMessage());
        }

        // Failures as data: collect both successes and failures
        List<Result> results = inputs.stream().map(s -> {
            try { return new Result(s, parse(s), null); }
            catch (IOException e) { return new Result(s, null, e.getMessage()); }
        }).toList();
        Map<Boolean, List<Result>> parts = results.stream()
                .collect(Collectors.partitioningBy(r -> r.error() == null));
        System.out.println("ok:     " + parts.get(true).stream().map(Result::value).toList());
        System.out.println("failed: " + parts.get(false).stream().map(Result::error).toList());
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        int n = 1_000_000;
        int[] data = IntStream.range(0, n).toArray();

        // 1. Plain loop
        long a = 0;
        for (int x : data) if (x % 2 == 0) a += x;

        // 2. Primitive stream: no boxing, JIT can inline the pipeline
        long b = Arrays.stream(data).filter(x -> x % 2 == 0).asLongStream().sum();

        // 3. Boxed stream: allocates Integer objects (slower, more garbage)
        long c = Arrays.stream(data).boxed().filter(x -> x % 2 == 0).mapToLong(Integer::longValue).sum();

        System.out.println("loop:           " + a);
        System.out.println("IntStream:      " + b);
        System.out.println("Stream<Integer>:" + c);
        System.out.println("all equal: " + (a == b && b == c));

        // Short-circuiting is where streams can beat a naive full loop
        int[] calls = {0};
        Optional<Integer> first = Arrays.stream(data).boxed()
                .filter(x -> { calls[0]++; return x > 10; }).findFirst();
        System.out.println("first > 10: " + first.get() + " after " + calls[0] + " checks of " + n);
        // For real numbers, measure with JMH rather than System.nanoTime on one run.
    }
}
